import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.stream.Collectors;

public class FunctionalPipelineDemo {
    public static void main(String[] args) {
        Supplier<List<String>> dataSupplier = () -> List.of("apple", "banana", "apricot", "blueberry");

        Predicate<String> startsWithA = s -> s.startsWith("a");

        Function<String, String> upperTransformer = String::toUpperCase;

        Consumer<String> consolePrinter = System.out::println;

        dataSupplier.get().stream()
            .filter(startsWithA)
            .map(upperTransformer)
            .forEach(consolePrinter);
    }
}
